#include "PluginEditor.h"
namespace {
const juce::Colour bg(0xffe8edf5), dark(0xff101522), text(0xffeaf2ff), muted(0xff91a0b6);
const juce::Colour colors[] = { juce::Colour(0xffff4da6), juce::Colour(0xff42d9ff), juce::Colour(0xffa45cff), juce::Colour(0xffffd83d), juce::Colour(0xff49d6a3), juce::Colour(0xff7aa7ff) };
const char* modules[] = {"01  DYNAMICS", "02  TONE", "03  SPACE", "04  SFX", "05  GENERATOR", "06  ANALYZER"};
}
ENGINEGURAudioProcessorEditor::ENGINEGURAudioProcessorEditor(ENGINEGURAudioProcessor& p):AudioProcessorEditor(&p),processor(p){
 setSize(1180,760);
 title.setText("ENGINEGURU",juce::dontSendNotification); title.setFont(juce::Font(juce::FontOptions(27,juce::Font::bold))); title.setColour(juce::Label::textColourId,colors[1]); addAndMakeVisible(title);
 subtitle.setText("SAMPLE-BASED SOUND DESIGN ENGINE  /  0.2.0",juce::dontSendNotification); subtitle.setColour(juce::Label::textColourId,muted); addAndMakeVisible(subtitle);
 status.setText(processor.getReferenceName(),juce::dontSendNotification); status.setColour(juce::Label::textColourId,text); addAndMakeVisible(status);
 for(auto* b:{&loadButton,&generateButton,&exportButton}){b->addListener(this);b->setColour(juce::TextButton::buttonColourId,juce::Colour(0xff202a3c));b->setColour(juce::TextButton::textColourOffId,text);addAndMakeVisible(b);}
 const juce::StringArray types{"Auto","Bass / 808","Kick","Snare","Clap","Closed Hat","Open Hat","Percussion","Other"}; for(int i=0;i<types.size();++i)typeBox.addItem(types[i],i+1); typeBox.setSelectedId(1);addAndMakeVisible(typeBox);
 for(auto* s:{&similarity,&amount}){s->setSliderStyle(juce::Slider::LinearHorizontal);s->setTextBoxStyle(juce::Slider::TextBoxRight,false,55,20);s->setRange(0,1,.01);addAndMakeVisible(s);} similarity.setValue(.72);amount.setValue(.22);
}
void ENGINEGURAudioProcessorEditor::paint(juce::Graphics& g){
 g.fillAll(bg); auto header=juce::Rectangle<float>(18,14,float(getWidth()-36),94);g.setColour(dark);g.fillRoundedRectangle(header,13);g.setColour(juce::Colour(0xff29364c));g.drawRoundedRectangle(header,13,1);
 const int margin=18,gap=12,top=122,w=(getWidth()-2*margin-2*gap)/3,h=270;
 for(int i=0;i<6;++i){int x=margin+(i%3)*(w+gap),y=top+(i/3)*(h+gap);juce::Rectangle<float> r(float(x),float(y),float(w),float(h));g.setColour(dark);g.fillRoundedRectangle(r,12);g.setColour(juce::Colour(0xff2b374b));g.drawRoundedRectangle(r,12,1);g.setColour(colors[i]);g.fillRoundedRectangle(r.removeFromTop(4),2);g.setColour(colors[i].withAlpha(.10f));g.fillEllipse(float(x+w-126),float(y+52),100,100);g.setColour(colors[i]);g.setFont(juce::Font(juce::FontOptions(14.0f,juce::Font::bold)));g.drawText(modules[i],x+18,y+16,w-36,24,juce::Justification::left); g.setColour(juce::Colour(0xff263247)); for(int k=0;k<2;++k){float cx=float(x+78+k*132),cy=float(y+142);g.fillEllipse(cx-43,cy-43,86,86);g.setColour(colors[i].withAlpha(.72f));g.drawEllipse(cx-43,cy-43,86,86,2.0f);g.setColour(juce::Colour(0xffdce7f7));g.drawEllipse(cx-27,cy-27,54,54,1.0f);g.setFont(11.0f);g.drawText(k==0?"CONTROL A":"CONTROL B",int(cx-55),y+194,110,18,juce::Justification::centred);g.setColour(juce::Colour(0xff263247));}}
 g.setColour(muted);g.setFont(12);g.drawText("INPUT  /  PROCESS  /  OUTPUT",22,getHeight()-24,360,16,juce::Justification::left);g.drawText("16 VARIATIONS  /  WAV 24-BIT",getWidth()-300,getHeight()-24,276,16,juce::Justification::right);
 g.setColour(text);g.setFont(12);g.drawText("COMPRESSOR  •  DE-ESSER",38,190,300,20,juce::Justification::centred);g.drawText("4-BAND EQ  •  FILTERS",438,190,300,20,juce::Justification::centred);g.drawText("REVERB  •  DELAY",838,190,280,20,juce::Justification::centred);g.drawText("PITCH  •  STEREO WIDTH",38,472,300,20,juce::Justification::centred);g.drawText("16 VARIATIONS  •  SIMILARITY / AMOUNT",438,472,300,20,juce::Justification::centred);g.drawText("REFERENCE SAMPLE  •  ANALYSIS",838,472,280,20,juce::Justification::centred);
 g.setColour(muted);g.drawText("Dynamics / Tone / Space / SFX control surfaces are UI placeholders in this foundation; effect DSP is not yet connected.",26,getHeight()-48,getWidth()-52,18,juce::Justification::centred);
}
void ENGINEGURAudioProcessorEditor::resized(){title.setBounds(38,24,270,38);subtitle.setBounds(40,64,380,20);loadButton.setBounds(455,42,132,38);status.setBounds(600,44,260,32);generateButton.setBounds(getWidth()-300,30,126,38);exportButton.setBounds(getWidth()-162,30,126,38);typeBox.setBounds(456,520,270,30);similarity.setBounds(456,560,270,32);amount.setBounds(456,600,270,32);}
void ENGINEGURAudioProcessorEditor::buttonClicked(juce::Button* b){
 if(b==&loadButton){fileChooser=std::make_unique<juce::FileChooser>("Choose WAV or AIFF sample",juce::File{},"*.wav;*.aif;*.aiff");juce::Component::SafePointer<ENGINEGURAudioProcessorEditor> safe(this);fileChooser->launchAsync(juce::FileBrowserComponent::openMode|juce::FileBrowserComponent::canSelectFiles,[safe](const juce::FileChooser& c){if(!safe)return;auto f=c.getResult();if(f.existsAsFile()){if(safe->processor.loadReference(f))safe->status.setText(safe->processor.getReferenceName(),juce::dontSendNotification);else safe->status.setText("Could not read audio file",juce::dontSendNotification);}safe->fileChooser.reset();});}
 else if(b==&generateButton){processor.setType(static_cast<eg::SoundType>(typeBox.getSelectedId()-1));processor.parameters.getParameter("similarity")->setValueNotifyingHost(float(similarity.getValue()));processor.parameters.getParameter("amount")->setValueNotifyingHost(float(amount.getValue()));processor.generateVariations();status.setText("16 variations generated",juce::dontSendNotification);}
 else if(b==&exportButton){fileChooser=std::make_unique<juce::FileChooser>("Export selected variation",juce::File::getSpecialLocation(juce::File::userMusicDirectory).getChildFile("ENGINEGURU_01.wav"),"*.wav");juce::Component::SafePointer<ENGINEGURAudioProcessorEditor> safe(this);fileChooser->launchAsync(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles,[safe](const juce::FileChooser& c){if(!safe)return;auto f=c.getResult();if(f!=juce::File{}&&safe->processor.exportVariation(safe->selected,f.withFileExtension("wav")))safe->status.setText("Exported variation 01",juce::dontSendNotification);safe->fileChooser.reset();});}
}
